/** Persistent per-turn records. Locks never silently recover; failed writes leave the prior record intact. */
import { CAMINS } from '../lib/arrel.mjs';
import { checkTaula } from '../gates/porta-olivera.mjs';
import fs from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { DESK, canonical, inside, relativePath, humanZone, hashFile, sha, json, turnPattern, receiptPattern,
  loadContract, saveContract, readContract, resolveRoute, parseDocument, anchored, validateSchema, validateSections, validateRegister } from './core.mjs';

const STORE = '.agents/runtime/turns';
function recordPath(root, id) {
  if (!turnPattern.test(id)) throw new Error('Identificador de torn invàlid');
  const target = path.join(root, STORE, `${id}.json`);
  if (!inside(canonical(root), canonical(target))) throw new Error('Registre fora del repositori');
  return target;
}
export function inventory(root, {files=[]} = {}) {
  const out = {};
  const skip = new Set(['node_modules', '.git', 'dist', '90_arxiu_historic', '.obsidian', 'runtime', '__pycache__']);
  function walk(rel) {
    const file = path.join(root, rel);
    if (!fs.existsSync(file)) return;
    const stat = fs.lstatSync(file);
    if (stat.isSymbolicLink()) { out[rel] = sha(`symlink:${fs.readlinkSync(file)}`); return; }
    if (stat.isDirectory()) {
      for (const e of fs.readdirSync(file).sort()) if (!skip.has(e)) walk(`${rel}/${e}`);
    } else if (stat.isFile()) out[rel] = hashFile(file);
  }
  for (const rel of ['src', 'tooling', 'scripts', 'tests', '.agents', '.codex', '.claude', '.github', '.husky', CAMINS.wiki,
    'package.json', 'package-lock.json', 'AGENTS.md', 'CLAUDE.md', 'vite.config.js', '.gitignore']) walk(rel);
  for (const file of files) {
    const rel=relativePath(root,file);
    if(fs.existsSync(path.join(root,rel))) out[rel]=hashFile(path.join(root,rel));
  }
  delete out['.agents/TORN_ACTIU.json'];
  return out;
}
export function changes(before, after) {
  return [...new Set([...Object.keys(before), ...Object.keys(after)])].filter(p => before[p] !== after[p]).sort();
}
export function readTurn(root, id, { closed = false, now = Date.now() } = {}) {
  const turn = json(recordPath(root, id));
  if (turn.turn_id !== id || turn.schema !== 'sdp.turn.v1' || !['opened', 'context_loaded', 'planned', 'verified', 'closed'].includes(turn.state)) throw new Error('Registre de torn invàlid');
  if (turn.state === 'closed' && !closed) throw new Error('Torn ja tancat');
  if (turn.state !== 'closed' && (!Number.isFinite(Date.parse(turn.expiresAt)) || Date.parse(turn.expiresAt) <= now)) throw new Error('Torn caducat');
  if (!turn.receipts || !turn.initial || !Array.isArray(turn.history)) throw new Error('Registre de torn incomplet');
  return turn;
}
function atomic(file, value) {
  const tmp = `${file}.${randomUUID()}.tmp`;
  try {
    fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, {flag:'wx', mode:0o600});
    fs.renameSync(tmp, file);
  } finally { if (fs.existsSync(tmp)) fs.unlinkSync(tmp); }
}
export function mutateTurn(root, id, operation) {
  const file = recordPath(root, id), lock = `${file}.lock`;
  const fd = fs.openSync(lock, 'wx', 0o600);
  try {
    const turn = readTurn(root, id);
    const result = operation(turn);
    turn.revision += 1;
    turn.updatedAt = new Date().toISOString();
    atomic(file, turn);
    return result ?? turn;
  } finally { fs.closeSync(fd); fs.unlinkSync(lock); }
}
function move(turn, state, action) {
  turn.state = state;
  turn.history.push({state, action, at:new Date().toISOString()});
}
export function openTurn(root, { actor = 'agent-local', scope = 'code' } = {}) {
  if (fs.existsSync(path.join(root, '.agents/SDP-LOCK'))) throw new Error('SDP-LOCK actiu');
  if (!['code', 'documents'].includes(scope)) throw new Error('Abast desconegut');
  const contract = loadContract(root, {templates:false});
  const turn_id = `torn_${randomUUID()}`;
  const now = new Date().toISOString();
  const turn = {schema:'sdp.turn.v1', turn_id, actor, scope, state:'opened', revision:0,
    createdAt:now, updatedAt:now, expiresAt:new Date(Date.now()+86400000).toISOString(),
    contractHash:contract.hash, humanInventoryVersion:1, initial:inventory(root), receipts:{}, plan:null, verification:null,
    history:[{state:'opened', action:'open', at:now}]};
  const file = recordPath(root, turn_id);
  fs.mkdirSync(path.dirname(file), {recursive:true});
  fs.writeFileSync(file, `${JSON.stringify(turn, null, 2)}\n`, {flag:'wx', mode:0o600});
  return turn;
}
export function deliverContext(root, id, {route:routeId, file}) {
  const contract = loadContract(root, {route:routeId}), route = resolveRoute(contract, {route:routeId});
  const rel = relativePath(root, file);
  if (!(route.destins || [DESK]).some(dir=>rel.startsWith(`${dir}/`)) || humanZone(rel) || path.basename(rel) === '00_index_escriptori.md') throw new Error('Destí de document no autoritzat');
  if (!/^\d{6}_\d{4}_[a-z0-9_]+\.md$/.test(path.basename(rel))) throw new Error('Nom termodinàmic invàlid');
  // Convocar agents exigix taula neta també fora d'un hook; una auditoria pot
  // documentar una taula bruta. create revalida ací, encara que ja tinga context.
  if (['prompt.local', 'prompt.consell'].includes(route.id)) {
    const taula = checkTaula(root);
    if (!taula.valid) throw new Error(`Convocatòria amb Escriptori brut:\n${taula.errors.join('\n')}`);
  }
  return mutateTurn(root, id, turn => {
    const receiptId = randomUUID();
    const receipt = {id:receiptId, route:route.id, routeVersion:route.version, file:rel,
      contractSnapshot:saveContract(root,contract), template:route.plantilla, templateHash:route.templateHash, issuedAt:new Date().toISOString()};
    turn.receipts[receiptId] = receipt;
    // New context invalidates verification, but retains an already bound plan.
    turn.verification = null;
    move(turn, turn.plan ? 'planned' : 'context_loaded', 'context');
    return {reflex:`sdp:${id}:${receiptId}`, route, template:route.templateText};
  });
}
export function validateDocument(root, content, file, { closed = false, readRecord, readSnapshot } = {}) {
  const errors = [];
  try {
    const parsed = parseDocument(content);
    const rel = relativePath(root, file);
    // The canonical desktop index is structural, never a substitute for a formal document.
    if (rel === `${DESK}/00_index_escriptori.md` && parsed.data.type === 'index') return validateSchema(parsed.data,loadContract(root,{templates:false}).schema);
    const m = typeof parsed.data.reflex === 'string' && receiptPattern.exec(parsed.data.reflex);
    if (!m) {
      errors.push('reflex: cal un rebut persistent emés per document.mjs context');
      errors.push(...validateSchema(parsed.data, loadContract(root, {templates: false}).schema));
    } else {
      const turn = readRecord ? readRecord(m[1]) : readTurn(root, m[1], {closed});
      const receipt = turn.receipts[m[2]];
      if (!receipt || receipt.id !== m[2] || receipt.file !== rel) throw new Error('Rebut absent o vinculat a un altre document');
      const contract = receipt.contractSnapshot ? readContract(root,receipt.contractSnapshot,readSnapshot) : loadContract(root,{route:receipt.route});
      if (!receipt.contractSnapshot && turn.contractHash !== contract.hash) throw new Error('Contracte del rebut caducat');
      errors.push(...validateSchema(parsed.data, contract.schema));
      const route = resolveRoute(contract, {route:receipt.route});
      if (receipt.templateHash !== route.templateHash || receipt.routeVersion !== route.version) throw new Error('Plantilla del rebut canviada');
      if (parsed.data.type !== route.tipus) errors.push('type: no correspon a la ruta del rebut');
      errors.push(...validateSections(parsed.body, route), ...validateRegister(parsed.body, contract));
      if (turn.state === 'closed' && turn.verification?.files?.[rel] !== sha(content)) errors.push('Artefacte modificat després del tancament');
    }
  } catch (e) { errors.push(e.message); }
  return errors;
}
export function bindPlan(root, id, file) {
  const rel = relativePath(root, file);
  const raw = fs.readFileSync(path.join(root, rel), 'utf8');
  const parsed = parseDocument(raw);
  const contract = loadContract(root);
  const errors = validateSchema(parsed.data, contract.schema);
  if (errors.length || parsed.data.type !== 'document') throw new Error(`Pla invàlid: ${errors.join('; ')}`);
  if (!rel.startsWith(`${DESK}/`) || humanZone(rel)) throw new Error('El pla ha de viure a l’Escriptori');
  return mutateTurn(root, id, turn => {
    if (!Object.keys(turn.receipts).length) throw new Error('Cal entregar context abans de vincular el pla');
    turn.plan = {file:rel, hash:sha(raw)};
    turn.verification = null;
    move(turn, 'planned', 'bind-plan');
  });
}
export function checkTurn(root, id, {turn:provided} = {}) {
  const errors = [];
  const turn = provided || readTurn(root, id);
  const contract = loadContract(root,{templates:false});
  if (!Object.values(turn.receipts).every(r=>r.contractSnapshot) && turn.contractHash !== contract.hash) errors.push('Contracte canviat durant el torn');
  if (!turn.plan || !fs.existsSync(path.join(root,turn.plan.file)) || hashFile(path.join(root, turn.plan.file)) !== turn.plan.hash) errors.push(`Pla absent o modificat: ${turn.plan?.file || '(sense pla)'}`);
  if (!['planned', 'verified'].includes(turn.state)) errors.push('El torn encara no està planificat');
  const current = inventory(root,{files:Object.values(turn.receipts).map(r=>r.file)}), changed = changes(turn.initial, current);
  // Explicit ownership avoids importing another agent's documents into this turn.
  // Human-zone and scope checks still use the complete repository delta.
  const owned = turn.ownedPaths ? new Set([...turn.ownedPaths,...Object.values(turn.receipts).map(r=>r.file)]) : null;
  const documents = new Set([...changed.filter(p=>!humanZone(p)).filter(p=>!turn.relocated?.includes(p)).filter(p=>!owned || owned.has(p)).filter(p => p.startsWith(`${DESK}/`) && p.endsWith('.md')),
    ...Object.values(turn.receipts).map(r => r.file)]);
  if (turn.scope === 'documents' && changed.some(p => /^(src|tooling|scripts|tests)\//.test(p) || /^package(?:-lock)?\.json$/.test(p))) errors.push('Canvis de codi fora de l’abast documental');
  for (const p of ['.agents/ESTAT.md', '.agents/LEDGER.md']) {
    if (current[p] === turn.initial[p] || !fs.readFileSync(path.join(root,p),'utf8').includes(id)) errors.push(`${p}: falta el relleu d’aquest torn`);
  }
  const humanBefore=turn.humanBaseline?.files || (turn.humanInventoryVersion===1 ? Object.fromEntries(Object.entries(turn.initial).filter(([p])=>humanZone(p))) : null);
  if(!humanBefore) errors.push('Vigilància humana sense inventari inicial; cal una migració explícita observada');
  else for(const file of changes(humanBefore,Object.fromEntries(Object.entries(current).filter(([p])=>humanZone(p))))) errors.push(`Zona humana modificada: ${file}`);
  const index = fs.readFileSync(path.join(root, DESK, '00_index_escriptori.md'),'utf8');
  for (const file of documents) {
    if (humanZone(file)) { errors.push(`Zona humana modificada: ${file}`); continue; }
    if (!fs.existsSync(path.join(root,file))) { errors.push(`Document eliminat sense relleu: ${file}`); continue; }
    const raw = fs.readFileSync(path.join(root,file),'utf8');
    errors.push(...validateDocument(root,raw,file,{readRecord:otherId=>otherId===id?turn:readTurn(root,otherId,{closed:true})}).map(e=>`${file}: ${e}`));
    if (file !== `${DESK}/00_index_escriptori.md` && !anchored(index,file)) errors.push(`Document sense àncora: ${file}`);
  }
  return {valid:errors.length===0, errors, current, changed, turn};
}
export function sealTurn(root, id, runChecks, {close = false} = {}) {
  return mutateTurn(root, id, turn => {
    const checked = checkTurn(root, id, {turn});
    if (!checked.valid) throw new Error(checked.errors.join('\n'));
    const result = runChecks(turn);
    if (!result.valid) throw new Error(result.errors.join('\n'));
    const after = inventory(root,{files:Object.values(turn.receipts).map(r=>r.file)});
    if (changes(checked.current,after).length) throw new Error('La comprovació ha modificat fitxers o hi ha escriptura concurrent');
    turn.verification = {at:new Date().toISOString(), files:after, checks:result.checks};
    move(turn,'verified','verify');
    if (close) move(turn,'closed','close');
    return {valid:true, turn_id:id, state:turn.state, checks:result.checks};
  });
}

// Ownership is explicit; absence keeps the conservative legacy whole-tree check.
export function ownPaths(root,id,files) {
  const paths=files.map(file=>relativePath(root,file));
  if(paths.some(humanZone)) throw new Error('No es pot reclamar la zona humana');
  return mutateTurn(root,id,turn=>{
    turn.ownedPaths=[...new Set([...(turn.ownedPaths||[]),...paths])];
    turn.verification=null;
    turn.history.push({action:'own-paths',files:paths,at:new Date().toISOString()});
  });
}
// A handoff registers a move already performed; it never fabricates a past reading.
export function handoffDocument(root,id,from,to) {
  const source=relativePath(root,from), target=relativePath(root,to);
  if(humanZone(source)||humanZone(target)) throw new Error('Zona humana protegida');
  if(![DESK,CAMINS.actes,CAMINS.arxiuHistoric].some(dir=>target.startsWith(`${dir}/`))) throw new Error('Destí de relleu no autoritzat');
  if(fs.existsSync(path.join(root,source))) throw new Error('La ruta original encara existeix');
  const raw=fs.readFileSync(path.join(root,target),'utf8'), digest=sha(raw);
  const match=receiptPattern.exec(parseDocument(raw).data.reflex||'');
  if(!match||match[1]!==id) throw new Error('Identitat del relleu divergent');
  return mutateTurn(root,id,turn=>{
    const receipt=turn.receipts[match[2]];
    if(!receipt||receipt.file!==source) throw new Error('Rebut del relleu absent');
    if(turn.plan?.file===source && turn.plan.hash!==digest) throw new Error('Pla modificat durant el relleu');
    receipt.file=target;
    receipt.moves=[...(receipt.moves||[]),{from:source,to:target,hash:digest,at:new Date().toISOString()}];
    if(turn.plan?.file===source) turn.plan.file=target;
    turn.ownedPaths=[...new Set([...(turn.ownedPaths||[]).filter(p=>p!==source),target])];
    // Preserve source history, while recognising that its absence is an intentional handoff.
    turn.relocated=[...(turn.relocated||[]),source];
    turn.verification=null;
    move(turn,turn.plan?'planned':'context_loaded','handoff');
  });
}
export function protectedTurnFiles(root) {
  const dir=path.join(root,STORE), out=new Set();
  if(!fs.existsSync(dir)) return out;
  for(const name of fs.readdirSync(dir).filter(n=>n.endsWith('.json'))) {
    const turn=json(path.join(dir,name));
    if(!turnPattern.test(turn.turn_id)||!Array.isArray(turn.history)||!turn.receipts) throw new Error(`Torn il·legible: ${name}`);
    // Closed receipts are protected too until an explicit archival handoff is supported.
    if(turn.plan?.file) out.add(turn.plan.file);
    for(const receipt of Object.values(turn.receipts)) out.add(receipt.file);
  }
  return out;
}

export function startHumanWatch(root,id) {
 return mutateTurn(root,id,turn=>{
  if(turn.humanInventoryVersion===1||turn.humanBaseline) throw new Error('Inventari humà ja establit; no es pot reiniciar');
  turn.humanBaseline={at:new Date().toISOString(),provenance:'observed-at-upgrade',files:Object.fromEntries(Object.entries(inventory(root)).filter(([file])=>humanZone(file)))};
  turn.history.push({action:'start-human-watch',at:turn.humanBaseline.at,note:'Observació actual; no acredita vigilància anterior ni autoria dels canvis previs.'});
 });
}

export function acknowledgeHumanZoneChanges(root, id, note = 'Reconeixement explícit de canvis a la zona humana') {
  return mutateTurn(root, id, turn => {
    if (!turn.humanBaseline) throw new Error('No hi ha vigilància humana activa al torn');
    const currentHumanZone = Object.fromEntries(Object.entries(inventory(root)).filter(([file]) => humanZone(file)));
    const changedFiles = changes(turn.humanBaseline.files, currentHumanZone);
    if (!changedFiles.length) throw new Error('No hi ha canvis a la zona humana per a reconéixer');

    turn.humanBaseline.files = currentHumanZone;
    turn.humanBaseline.at = new Date().toISOString();
    turn.humanBaseline.provenance = 'acknowledged';
    turn.verification = null;
    turn.history.push({ action: 'acknowledge-human-zone-changes', files: changedFiles, at: turn.humanBaseline.at, note });
  });
}

/** Escriptura de draft i àncora: revalida en executar, mai confia en el hook.
 * L'índex es llig per descriptor O_NOFOLLOW i es reemplaça amb rename; mai
 * escrivim al seu inode original, que un altre procés podria haver reenllaçat.
 */
import fs from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { CAMINS } from '../lib/arrel.mjs';
import { checkTaula } from '../gates/porta-olivera.mjs';

const same = (a, b) => a.dev === b.dev && a.ino === b.ino;
const regular = stat => stat.isFile() && stat.nlink === 1;
const failure = () => new Error('Destí documental substituït, enllaçat o fora de l’arrel.');

function parents(root, file, create = false) {
  const rel = path.relative(root, file);
  if (!rel || rel === '..' || rel.startsWith(`..${path.sep}`) || path.isAbsolute(rel)) throw failure();
  let current = root;
  for (const part of rel.split(path.sep).slice(0, -1)) {
    current = path.join(current, part);
    let stat;
    try { stat = fs.lstatSync(current); }
    catch (error) {
      if (error.code !== 'ENOENT') throw error;
      if (!create) return;
      fs.mkdirSync(current); stat = fs.lstatSync(current);
    }
    if (!stat.isDirectory() || stat.isSymbolicLink() || fs.realpathSync(current) !== current) throw failure();
  }
}
function openIndex(root) {
  const file = path.join(root, CAMINS.indexEscriptori);
  parents(root, file);
  const fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);
  try {
    const stat = fs.fstatSync(fd);
    if (!regular(stat)) throw failure();
    parents(root, file);
    const named = fs.lstatSync(file);
    if (!regular(named) || named.isSymbolicLink() || !same(stat, named)) throw failure();
    return { file, fd, stat, content: fs.readFileSync(fd, 'utf8') };
  } catch (error) { fs.closeSync(fd); throw error; }
}
function assertOwned(root, file, stat, fd) {
  parents(root, file);
  const named = fs.lstatSync(file), opened = fs.fstatSync(fd);
  if (!regular(named) || !regular(opened) || named.isSymbolicLink() || !same(named, stat) || !same(opened, stat)) throw failure();
}
function removeOwned(root, file, stat) {
  // Rollback mai elimina un fitxer que una altra operació ha posat al mateix nom.
  try {
    parents(root, file);
    const named = fs.lstatSync(file);
    if (!named.isSymbolicLink() && same(named, stat)) fs.unlinkSync(file);
  } catch (error) { if (error.code !== 'ENOENT') return; }
}
export function checkDraftDestinations(root, file) {
  root = fs.realpathSync(root);
  parents(root, file);
  try {
    fs.lstatSync(file);
    const error = new Error('EEXIST: el draft ja existix.'); error.code = 'EEXIST'; throw error;
  } catch (error) { if (error.code !== 'ENOENT') throw error; }
  const index = openIndex(root);
  fs.closeSync(index.fd);
}
function indexProse(index) {
  // Conserva offsets per inserir sense alterar comentaris ni exemples de codi.
  const mask = text => text.replace(/[^\r\n]/g, ' ');
  let fence = null;
  return index.replace(/<!--[\s\S]*?-->/g, mask).split(/(?<=\n)/).map(line => {
    const mark = /^ {0,3}(`{3,}|~{3,})/.exec(line);
    if (mark) {
      if (!fence) fence = mark[1];
      else if (mark[1][0] === fence[0] && mark[1].length >= fence.length) fence = null;
      return mask(line);
    }
    return fence ? mask(line) : line;
  }).join('').replace(/`[^`]*`/g, mask);
}
function anchorDraft(index, anchor, firstLevel) {
  if (!firstLevel) return index.includes(anchor) ? index : `${index}\n- ${anchor}\n`;
  const prose = indexProse(index);
  const active = /^##[ \t]+Activitat en curs[^\n]*(?:\r?\n|$)/m.exec(prose);
  if (!active) return `${index}\n## Activitat en curs\n\n- ${anchor}\n`;
  const start = active.index + active[0].length;
  const next = /^##[ \t]/m.exec(prose.slice(start));
  const end = next ? start + next.index : index.length;
  if (prose.slice(start, end).includes(anchor)) return index;
  return `${index.slice(0, start)}\n- ${anchor}\n${index.slice(start)}`;
}
export function writeIndexedDraft(root, file, content, { requireCleanTable = false } = {}) {
  root = fs.realpathSync(root);
  checkDraftDestinations(root, file);
  const lock = path.join(root, CAMINS.agents, 'runtime', 'document-create.lock');
  parents(root, lock);
  const lockFd = fs.openSync(lock, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | fs.constants.O_NOFOLLOW, 0o600);
  const lockStat = fs.fstatSync(lockFd);
  let index, created, temporary, committed = false;
  try {
    assertOwned(root, lock, lockStat, lockFd);
    index = openIndex(root);
    // Revalida dins del lock: context pot haver emés el rebut abans que un
    // altre actor deixe un document nou sense classificar. No es mou res.
    if (requireCleanTable) {
      const taula = checkTaula(root);
      if (!taula.valid) throw new Error(`Convocatòria amb Escriptori brut:\n${taula.errors.join('\n')}`);
    }
    parents(root, file, true);
    const fd = fs.openSync(file, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | fs.constants.O_NOFOLLOW, 0o600);
    created = { fd, stat: fs.fstatSync(fd) };
    assertOwned(root, file, created.stat, fd);
    fs.writeFileSync(fd, content, 'utf8'); fs.fsyncSync(fd);
    const anchor = `[[${path.basename(file, '.md')}]]`;
    const anchored = anchorDraft(index.content, anchor, path.dirname(file) === path.join(root, CAMINS.escriptori));
    if (anchored !== index.content) {
      const tempFile = `${index.file}.${randomUUID()}.tmp`;
      parents(root, tempFile);
      const tempFd = fs.openSync(tempFile, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | fs.constants.O_NOFOLLOW, index.stat.mode & 0o777);
      temporary = { file: tempFile, fd: tempFd, stat: fs.fstatSync(tempFd) };
      assertOwned(root, tempFile, temporary.stat, tempFd);
      fs.writeFileSync(tempFd, anchored, 'utf8'); fs.fsyncSync(tempFd);
    }
    // CAS de bytes i inode: preserva també les edicions concurrents legítimes.
    const latest = openIndex(root);
    try { if (!same(index.stat, latest.stat) || index.content !== latest.content) throw failure(); }
    finally { fs.closeSync(latest.fd); }
    assertOwned(root, index.file, index.stat, index.fd);
    assertOwned(root, file, created.stat, created.fd);
    if (temporary) {
      assertOwned(root, temporary.file, temporary.stat, temporary.fd);
      fs.renameSync(temporary.file, index.file);
    }
    committed = true;
  } finally {
    if (index) fs.closeSync(index.fd);
    if (created) {
      fs.closeSync(created.fd);
      if (!committed) removeOwned(root, file, created.stat);
    }
    if (temporary) { fs.closeSync(temporary.fd); removeOwned(root, temporary.file, temporary.stat); }
    fs.closeSync(lockFd); removeOwned(root, lock, lockStat);
  }
}

#!/usr/bin/env node
/** Porta Olivera · higiene d'Escriptori en la transició Pla → Petorreta.
 *
 *  El problema que resol, dit sense adornar-lo: la precondició d'higiene («neteja
 *  l'Escriptori i escriu el Pla abans de cridar les altres IAs») vivia a les
 *  Lliçons d'una skill, i el moment de decisió té davant un altre document. Una
 *  regla que ha de disparar en el moment X ha de viure al canal que corre en el
 *  moment X. Qualsevol altra ubicació és decorativa.
 *
 *  Per això açò no és un recordatori: és una porta `PreToolUse`. Quan algú escriu
 *  una petorreta a l'Escriptori, comprova tres coses i bloqueja si no es complixen:
 *
 *    1. L'Escriptori està net (`checkTaula`, la definició única d'AGENTS §0.1):
 *       cap prompt, auditoria, pla o bundle consumit de jornades anteriors solt
 *       damunt la taula, la Safata d'Entrada buida, cada document ancorat a
 *       l'índex i cap àncora a un document absent.
 *    2. Hi ha un Pla d'Implementació d'aquesta jornada: la pissarra compartida
 *       existix abans de convocar ningú.
 *    3. La petorreta porta la secció 0 i cap casella sense marcar. La secció es
 *       pot dir «0. Abans de generar» o «0. Preflight», que és el nom que du la
 *       plantilla `prompt_local.md`: un prompt fet bé des de la plantilla no pot
 *       quedar bloquejat pel nom de la capçalera.
 *
 *  Viu per declaració, no per data (260930). A les 00:00 el rellotge convertia en
 *  brossa el prompt que s'estava executant. Ara decidix qui treballa: tot document
 *  llistat davall d'una capçalera «## Activitat en curs» de l'índex continua viu,
 *  siga del dia que siga, i `ranci()` no el toca. La tria és explícita i
 *  auditable: l'informe la mostra sencera.
 *
 *  L'informe (`npm run porta:olivera`) jutja la taula, no la petorreta: ix amb 0
 *  quan `checkTaula` és vàlid. El «pla de hui» només té sentit quan s'escriu una
 *  petorreta, i per això el demana el hook i no l'informe; si no, un Escriptori
 *  acabat de netejar al matí no passaria mai abans del primer pla.
 *
 *  No esborra res mai. `--arxiva` mou a `90_arxiu_historic/` i despenja les
 *  entrades de l'índex, i és una ordre explícita: AGENTS §5 prohibix l'esborrat
 *  automàtic i el trasllat silenciós d'allò que encara pot estar viu.
 *
 *  Ús:
 *    porta-olivera.mjs [--informe]          # auditoria de l'Escriptori (eixida 1 si brut); mai llig stdin
 *    porta-olivera.mjs --hook               # hook: llig el payload per stdin
 *    porta-olivera.mjs --arxiva [--sec]     # mou els consumits de jornades anteriors
 *    porta-olivera.mjs --arxiva --nom F.md [--nom G.md] [--sec]
 *                                           # mou documents de torn concrets, també d'avui
 *
 *  El mode hook és explícit: sense bandera, `readFileSync(0)` esperava un EOF que
 *  un terminal (o un pipe que ningú tanca) no envia mai, i la porta es penjava
 *  just quan la skill manava executar-la.
 */
import { CAMINS, arrelSegura } from '../lib/arrel.mjs';
import fs from 'node:fs';
import path from 'node:path';
import tty from 'node:tty';
import { pathToFileURL } from 'node:url';

// La ubicació de l'eina resol l'arrel. Conservar l'error permet importar les
// funcions amb una arrel explícita en fixtures, sense donar cap verd implícit.
let errorArrel = null;
export const ARREL = (() => {
  try { return process.env.SDP_ARREL ? path.resolve(process.env.SDP_ARREL) : arrelSegura(); }
  catch (error) { errorArrel = error; return null; }
})();
function arrelPerDefecte() {
  if (ARREL) return ARREL;
  throw errorArrel;
}
const ESCRIPTORI = CAMINS.escriptori;
const ARXIU = CAMINS.arxiuHistoric;
const INDEX = CAMINS.indexEscriptori;

/** Categories de treball d'un torn: naixen, servixen i se'n van a l'arxiu. */
export const TRANSITORIES = /^(prompt|macro_prompt|micro_prompt|petorreta|auditoria|informe|bundle|macro_bundle|micro_bundle|pla|acta|tasques)$/;

const NOM = /^(\d{6})_(\d{4})_([a-z0-9]+(?:_[a-z0-9]+)*)\.md$/;

/** Capçalera que declara vius els documents que llista. N'hi pot haver més d'una, amb sufix. */
const ACTIVITAT = /^##[ \t]+Activitat en curs[^\n]*\n([\s\S]*?)(?=^##[ \t]|(?![\s\S]))/gm;

/** Secció 0 d'una petorreta: el nom de les proves antigues i el de la plantilla viva. */
const SECCIO_ZERO = /^##[ \t]+0\.[ \t]+(?:Abans de generar|Preflight)[^\n]*\n([\s\S]*?)(?=^#{1,2}[ \t]+|(?![\s\S]))/m;

/** `aammdd` d'avui, en hora local: és el segell que porten els noms de fitxer. */
export function avui(ara = new Date()) {
  const p = (n) => String(n).padStart(2, '0');
  return `${p(ara.getFullYear() % 100)}${p(ara.getMonth() + 1)}${p(ara.getDate())}`;
}

/** Documents solts de l'Escriptori, amb data, categoria i cognom. */
export function inventari(arrel = arrelPerDefecte()) {
  const dir = path.join(arrel, ESCRIPTORI);
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isFile() && !e.name.startsWith('.') && e.name.endsWith('.md'))
    .map((e) => {
      const m = NOM.exec(e.name);
      if (!m) return null;
      const [, data, hora, resta] = m;
      const categoria = resta.startsWith('pla_implementacio') ? 'pla' : resta.split('_')[0];
      return { nom: e.name, rel: `${ESCRIPTORI}/${e.name}`, data, hora, categoria, resta };
    })
    .filter(Boolean);
}

/**
 * Noms (sense `.md`) que l'índex declara vius davall de qualsevol «## Activitat en
 * curs». Només compten les àncores planes, com a `ancoratge()`: una àncora amb `/`
 * apunta fora del primer nivell i no pot protegir cap document de la taula.
 */
export function vius(arrel = arrelPerDefecte()) {
  const p = path.join(arrel, INDEX);
  const text = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : '';
  const noms = new Set();
  for (const bloc of text.matchAll(ACTIVITAT)) {
    for (const a of bloc[1].matchAll(/\[\[([^\]|#]+)/g)) {
      const nom = a[1].trim();
      if (nom && !nom.includes('/')) noms.add(nom.replace(/\.md$/, ''));
    }
  }
  return noms;
}

/** El que hauria d'estar a l'arxiu: categoria de torn, data anterior a hui i cap declaració de viu. */
export function ranci(arrel = arrelPerDefecte(), dia = avui()) {
  const viu = vius(arrel);
  return inventari(arrel).filter((d) => TRANSITORIES.test(d.categoria) && d.data < dia && !viu.has(d.nom.replace(/\.md$/, '')));
}

/** Pissarra compartida d'aquesta jornada. */
export function plaDeHui(arrel = arrelPerDefecte(), dia = avui()) {
  return inventari(arrel).filter((d) => /^pla_implementacio(?:_|$)/.test(d.resta) && d.data === dia);
}

/**
 * Elements de la Safata d'Entrada, que ha d'estar sempre buida (AGENTS §12). La
 * carpeta es busca sense distingir caixa: el codi en conserva `00_Bandeja_d_Entrada`
 * i el disc du `00_bandeja_d_entrada`, i a Linux una comparació exacta no la veuria.
 */
export function safata(arrel = arrelPerDefecte()) {
  const dir = path.join(arrel, ESCRIPTORI);
  if (!fs.existsSync(dir)) return { carpeta: null, elements: [] };
  const carpeta = fs.readdirSync(dir, { withFileTypes: true })
    .find((e) => e.isDirectory() && /^00_bandeja_d_entrada$/i.test(e.name));
  if (!carpeta) return { carpeta: null, elements: [] };
  const elements = fs.readdirSync(path.join(dir, carpeta.name)).filter((n) => !n.startsWith('.')).sort();
  return { carpeta: `${ESCRIPTORI}/${carpeta.name}`, elements };
}

/** Documents de l'Escriptori sense àncora a l'índex, i àncores a documents absents. */
export function ancoratge(arrel = arrelPerDefecte()) {
  const indexPath = path.join(arrel, INDEX);
  const text = fs.existsSync(indexPath) ? fs.readFileSync(indexPath, 'utf8') : '';
  const ancores = [...text.matchAll(/\[\[([^\]]+)\]\]/g)].map((m) => m[1].split('|')[0].trim());
  const docs = inventari(arrel).filter((d) => d.nom !== '00_index_escriptori.md');
  const noms = new Set(docs.map((d) => d.nom.replace(/\.md$/, '')));
  const ancorats = new Set(ancores.map((a) => path.basename(a)));
  return {
    senseAncora: docs.filter((d) => !ancorats.has(d.nom.replace(/\.md$/, ''))).map((d) => d.nom),
    // Només comptem àncores planes: les que porten `/` apunten fora de l'Escriptori.
    fantasma: ancores.filter((a) => !a.includes('/') && !noms.has(a) && a !== '00_index_escriptori')
  };
}

/**
 * Escriptori net: la definició única (AGENTS §0.1) i el que jutja l'informe.
 * Brossa, Safata i àncores; el «pla de hui» no hi entra, és cosa de la petorreta.
 */
export function checkTaula(arrel = arrelPerDefecte(), { dia = avui() } = {}) {
  const errors = [];
  for (const [rel, directory] of [[ESCRIPTORI, true], [INDEX, false]]) {
    try {
      const stat = fs.lstatSync(path.join(arrel, rel));
      if (stat.isSymbolicLink() || !(directory ? stat.isDirectory() : stat.isFile()))
        errors.push(`Estructura de l'Escriptori invàlida: ${rel}`);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
      errors.push(`Estructura de l'Escriptori absent: ${rel}`);
    }
  }
  if (errors.length) return { valid: false, errors };

  const bruts = ranci(arrel, dia);
  if (bruts.length) {
    errors.push(`Escriptori sense classificar: ${bruts.length} document(s) de jornades anteriors encara damunt la taula (${bruts.map((d) => d.nom).join(', ')}). Arxiva'ls amb: node tooling/gates/porta-olivera.mjs --arxiva, o declara'ls vius davall de «## Activitat en curs» a ${INDEX}`);
  }

  const bustia = safata(arrel);
  if (bustia.elements.length) {
    errors.push(`Safata d'entrada amb ${bustia.elements.length} element(s) (${bustia.carpeta}: ${bustia.elements.slice(0, 5).join(', ')}${bustia.elements.length > 5 ? '…' : ''}). La Safata s'ha de buidar sempre (AGENTS §12).`);
  }

  const anc = ancoratge(arrel);
  if (anc.senseAncora.length) errors.push(`Sense àncora a l’índex: ${anc.senseAncora.join(', ')}`);
  if (anc.fantasma.length) errors.push(`Àncores a documents absents: ${anc.fantasma.join(', ')}`);

  return { valid: errors.length === 0, errors };
}

/** Les tres comprovacions de la transició Pla → Petorreta: la taula, el pla i la secció 0. */
export function checkOlivera(arrel = arrelPerDefecte(), { contingut = null, dia = avui() } = {}) {
  const errors = [...checkTaula(arrel, { dia }).errors];

  if (!plaDeHui(arrel, dia).length) {
    errors.push(`Cap Pla d'Implementació de hui (${dia}) a l'Escriptori. Les altres IAs arriben a una habitació sense pissarra. Genera'l abans: node tooling/wiki/document.mjs context --turn-id ID --route pla.implementacio --file ${ESCRIPTORI}/${dia}_HHMM_pla_implementacio_COGNOM.md`);
  }

  if (typeof contingut === 'string') {
    const section = SECCIO_ZERO.exec(contingut);
    if (!section) {
      errors.push("La petorreta no porta la secció 0: «0. Abans de generar (per a l'autor, no per al destinatari)» o «0. Preflight», com la plantilla prompt_local.md. És la precondició d'higiene i ha de viatjar dins del document, no a la memòria de qui l'escriu.");
    } else if (/^[ \t]*[-*+][ \t]+\[[ \t]\]/m.test(section[1])) {
      errors.push('La secció 0 té caselles sense marcar. Cap petorreta ix del Mas amb la llista a mitges.');
    }
  }

  return { valid: errors.length === 0, errors };
}

/** És una petorreta de l'Escriptori? Només eixe cas dispara la porta. */
export function esPetorreta(rel) {
  const pla = rel.split(path.sep).join('/');
  if (!pla.startsWith(`${ESCRIPTORI}/`)) return false;
  if (pla.slice(ESCRIPTORI.length + 1).includes('/')) return false;
  const m = NOM.exec(path.basename(pla));
  return !!m && /^(prompt|macro_prompt|micro_prompt|petorreta)_/.test(m[3]);
}

/* ── Hook ─────────────────────────────────────────────────────────────────── */

/**
 * Una redirecció de shell escriu sense passar per cap eina de fitxers, i eixa és
 * la via per la qual els documents d'aquesta jornada van arribar al disc sense
 * rebut. Ací només mirem el destí: si apunta a una petorreta de l'Escriptori,
 * la porta actua igual que amb una escriptura normal.
 */
export function destiDeShell(ordre) {
  if (typeof ordre !== 'string') return null;
  const m = /(?:>>?|\|\s*tee(?:\s+-a)?)\s*(?:'([^']+)'|"([^"]+)"|(\S+))/.exec(ordre);
  const desti = m && (m[1] || m[2] || m[3]);
  return desti && esPetorreta(desti.replace(/^\.\//, '')) ? desti : null;
}

function rutaIContingut(payload) {
  const ti = payload.tool_input;
  const ta = payload.toolArgs;
  const dialecte = ti ? 'claude' : 'antigravity';
  const fitxer = ti?.file_path || ti?.notebook_path || ta?.TargetFile
    || destiDeShell(ti?.command || ta?.Command || ta?.CommandLine) || null;
  const contingut = typeof ti?.content === 'string' ? ti.content
    : typeof ta?.CodeContent === 'string' ? ta.CodeContent
      : null;
  return { dialecte, fitxer, contingut };
}

export function checkPayload(payload, arrel = arrelPerDefecte()) {
  if (!payload || typeof payload !== 'object' || !payload.tool_name || (!payload.tool_input && !payload.toolArgs)) return {code: 2, errors: ['Payload de hook incomplet']};
  const { dialecte, fitxer, contingut } = rutaIContingut(payload);
  if (!fitxer) {
    const reads = ['Read', 'Glob', 'Grep', 'read_file', 'view_file', 'list_dir', 'grep_search', 'search_code'];
    return reads.includes(payload.tool_name) ? {code: 0, errors: []} : {code: 2, errors: ['Hook sense destí verificable; usa hooks-local per a shell i eines no documentals']};
  }
  const rel = path.isAbsolute(fitxer) ? path.relative(arrel, fitxer) : fitxer;
  if (!esPetorreta(rel)) return { code: 0, errors: [] };
  if (typeof contingut !== 'string') return {code: 2, errors: ['Petorreta sense contingut complet verificable; usa escriptura documental explícita'], file: rel};
  const r = checkOlivera(arrel, { contingut });
  return { code: r.valid ? 0 : (dialecte === 'claude' ? 2 : 1), errors: r.errors, file: rel };
}

/* ── Arxivat explícit ─────────────────────────────────────────────────────── */

/**
 * Què mouria `--arxiva`. Sense noms: els rancis (jornades anteriors, no declarats
 * vius). Amb noms: exactament eixos documents, també d'avui. Cada nom es valida
 * abans de moure res, i un sol nom dolent atura el lot sencer: subcarpetes, noms
 * que no són a la taula i categories que no són de torn. L'índex, els recursos i
 * les notes es queden on són, i per nom tampoc ixen.
 */
export function arxivables(arrel = arrelPerDefecte(), { noms = [], dia = avui() } = {}) {
  if (!noms.length) return ranci(arrel, dia);
  const inv = inventari(arrel);
  const triats = [];
  for (const cru of noms) {
    const pla = String(cru).split('\\').join('/').replace(/^\.\//, '');
    const solt = pla.startsWith(`${ESCRIPTORI}/`) ? pla.slice(ESCRIPTORI.length + 1) : pla;
    if (!solt || solt.includes('/')) {
      throw new Error(`--nom ${cru}: només s'arxiven per nom documents solts del primer nivell de ${ESCRIPTORI}; les subcarpetes (Safata, 01_produccio, 02_investigacio_ia) queden fora`);
    }
    const nom = solt.endsWith('.md') ? solt : `${solt}.md`;
    const d = inv.find((x) => x.nom === nom);
    if (!d) throw new Error(`--nom ${cru}: no és cap document solt de ${ESCRIPTORI} amb nom aammdd_hhmm_categoria_titol.md`);
    if (!TRANSITORIES.test(d.categoria)) {
      throw new Error(`--nom ${cru}: la categoria «${d.categoria}» no és de torn; per nom només ixen prompts, petorretes, auditories, informes, bundles, plans, actes i tasques`);
    }
    if (!triats.includes(d)) triats.push(d);
  }
  return triats;
}

/** Trasllat a l'arxiu. Amb `sec` només respon què faria: cap fitxer mogut ni índex tocat. */
export function arxiva(arrel = arrelPerDefecte(), { noms = [], sec = false, dia = avui() } = {}) {
  const bruts = arxivables(arrel, { noms, dia });
  if (!bruts.length) return { moguts: [], index: false, sec };
  const desti = path.join(arrel, ARXIU);

  if (sec) {
    const moguts = bruts.map((d) => ({ ...d, nota: fs.existsSync(path.join(desti, d.nom)) ? 'simulació: ja existix a l’arxiu; no es mouria' : 'simulació: es mouria' }));
    return { moguts, index: false, sec };
  }

  fs.mkdirSync(desti, { recursive: true });
  const moguts = [];
  for (const d of bruts) {
    const origen = path.join(arrel, d.rel);
    const final = path.join(desti, d.nom);
    if (fs.existsSync(final)) { moguts.push({ ...d, nota: 'ja existia a l’arxiu; no es sobreescriu' }); continue; }
    fs.renameSync(origen, final);
    moguts.push({ ...d, nota: 'mogut' });
  }

  // Despenjar les àncores dels documents que ja no viuen a l'Escriptori.
  const indexPath = path.join(arrel, INDEX);
  let tocat = false;
  if (fs.existsSync(indexPath)) {
    const noms = new Set(moguts.filter((m) => m.nota === 'mogut').map((m) => m.nom.replace(/\.md$/, '')));
    const linies = fs.readFileSync(indexPath, 'utf8').split('\n');
    const netes = linies.filter((l) => {
      const m = /^\s*-\s*\[\[([^\]]+)\]\]/.exec(l);
      return !(m && noms.has(path.basename(m[1].split('|')[0].trim())));
    });
    if (netes.length !== linies.length) {
      fs.writeFileSync(indexPath, netes.join('\n'), 'utf8');
      tocat = true;
    }
  }
  return { moguts, index: tocat, sec };
}

/* ── CLI ──────────────────────────────────────────────────────────────────── */

const US = 'Ús: porta-olivera.mjs [--informe] | --hook | --arxiva [--nom FITXER.md]... [--sec]';

/** Banderes de la línia d'ordres. Una bandera desconeguda no es llig com a informe: falla. */
function opcions(argv) {
  const o = { informe: false, hook: false, arxiva: false, sec: false, noms: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--informe') o.informe = true;
    else if (a === '--hook') o.hook = true;
    else if (a === '--arxiva') o.arxiva = true;
    else if (a === '--sec') o.sec = true;
    else if (a === '--nom' || a.startsWith('--nom=')) {
      const valor = a === '--nom' ? argv[++i] : a.slice('--nom='.length);
      if (!valor || valor.startsWith('--')) throw new Error(`--nom necessita el nom d'un document. ${US}`);
      o.noms.push(valor);
    } else throw new Error(`Argument desconegut: ${a}. ${US}`);
  }
  if ([o.informe, o.hook, o.arxiva].filter(Boolean).length > 1) throw new Error(`Tria un sol mode. ${US}`);
  if ((o.noms.length || o.sec) && !o.arxiva) throw new Error(`--nom i --sec només valen amb --arxiva. ${US}`);
  return o;
}

function informe(arrel, dia = avui()) {
  const taula = checkTaula(arrel, { dia });
  if (taula.errors.some(error => error.startsWith("Estructura de l'Escriptori"))) {
    for (const error of taula.errors) console.error(`[Porta Olivera] ${error}`);
    return 1;
  }
  const docs = inventari(arrel);
  const presents = new Set(docs.map((d) => d.nom.replace(/\.md$/, '')));
  const viu = [...vius(arrel)].filter((n) => presents.has(n)).sort();
  const bruts = ranci(arrel, dia);
  const bustia = safata(arrel);
  const anc = ancoratge(arrel);
  const pla = plaDeHui(arrel, dia);
  console.log(`[Porta Olivera] Escriptori: ${docs.length} documents solts.`);
  console.log(viu.length
    ? `🌿 Declarats vius a «## Activitat en curs» (es conserven): ${viu.join(', ')}`
    : '🌿 Cap document de la taula declarat viu a «## Activitat en curs».');
  if (bruts.length) {
    console.log(`❌ ${bruts.length} de jornades anteriors sense declarar vius (han d'anar a ${ARXIU}/):`);
    for (const d of bruts) console.log(`   · ${d.nom}`);
  } else console.log('✅ Cap document consumit de jornades anteriors.');
  console.log(bustia.elements.length ? `❌ Safata d'entrada amb ${bustia.elements.length} element(s): ${bustia.elements.join(', ')}` : "✅ Safata d'entrada buida.");
  if (anc.senseAncora.length) console.log(`❌ Sense àncora a l'índex: ${anc.senseAncora.join(', ')}`);
  if (anc.fantasma.length) console.log(`❌ Àncores a documents absents (fan caure la porta): ${anc.fantasma.join(', ')}`);
  console.log(pla.length
    ? `ℹ️ Pla d'Implementació de hui: ${pla.map((d) => d.nom).join(', ')}`
    : "ℹ️ Cap Pla d'Implementació de hui: el demana l'escriptura d'una petorreta, no l'Escriptori net.");
  return checkTaula(arrel, { dia }).valid ? 0 : 1;
}

function main(argv = process.argv.slice(2)) {
  const o = opcions(argv);
  const arrel = arrelPerDefecte();

  if (o.arxiva) {
    const r = arxiva(arrel, { noms: o.noms, sec: o.sec });
    if (o.sec) console.log('[Porta Olivera] Simulació (--sec): no es mou cap fitxer ni es toca l’índex.');
    if (!r.moguts.length) console.log('[Porta Olivera] Res a arxivar.');
    for (const m of r.moguts) console.log(`   · ${m.nom} → ${ARXIU}/ (${m.nota})`);
    if (r.index) console.log(`   · ${INDEX} actualitzat.`);
    if (r.moguts.some((m) => m.nota === 'mogut')) console.log('   Si algun portava rebut de torn: node tooling/wiki/document.mjs handoff --turn-id ID --file ORIGEN --to DESTÍ');
    process.exitCode = 0;
    return;
  }

  if (!o.hook) { process.exitCode = informe(arrel); return; }

  // Mode hook: sense payload no hi ha res a jutjar, i no es pot fingir un verd.
  if (tty.isatty(0)) {
    console.error('[PORTA-OLIVERA] --hook espera el payload JSON per stdin; des d’un terminal usa el mode informe (sense bandera).');
    process.exitCode = 2;
    return;
  }
  const raw = fs.readFileSync(0, 'utf8');
  if (!raw.trim()) {
    console.error('[PORTA-OLIVERA] --hook amb payload buit; cap comprovació executada.');
    process.exitCode = 2;
    return;
  }

  // Un payload il·legible no acredita cap comprovació: falla tancat.
  let result;
  try { result = checkPayload(JSON.parse(raw), arrel); }
  catch (e) {
    console.error(`[PORTA-OLIVERA] payload il·legible (${e.message}); cap comprovació executada.`);
    result = { code: 2, errors: ['Payload il·legible: cap autorització'] };
  }

  if (result.errors.length) {
    console.error(`[PORTA-OLIVERA] BLOQUEIG · ${result.file ?? '(sense destí)'}\n${result.errors.map((e) => `- ${e}`).join('\n')}\nLa Reunió a l'Olivera comença amb la taula classificada i el Pla damunt.`);
  }
  process.exitCode = result.code;
}

// `import.meta.url` porta el camí REAL i `process.argv[1]` el camí tal com
// s'ha escrit: sota un symlink (/var cap a /private/var a macOS, i qualsevol
// fixture de proves a os.tmpdir()) no coincidixen, el mòdul es carrega en
// silenci i la porta ix 0 sense comprovar res. Resoldre el symlink és el que
// fa que la guarda parle sempre.
if (process.argv[1] && import.meta.url === pathToFileURL(fs.realpathSync(process.argv[1])).href) {
  try { main(); } catch (e) { console.error(e.message); process.exitCode = 2; }
}

#!/usr/bin/env node
import { esMain } from '../lib/arrel.mjs';
/** Explicit, host-independent delivery of templates and generation of indexed drafts. */
import fs from 'node:fs';
import path from 'node:path';
import yaml from 'js-yaml';
import { ROOT, options } from '../documental/cli.mjs';
import { loadContract, validateSchema, parseDocument } from '../documental/core.mjs';
import { checkDraftDestinations, writeIndexedDraft } from '../documental/draft-write.mjs';
import { deliverContext, bindPlan, validateDocument, ownPaths, handoffDocument } from '../documental/turns.mjs';

export function draft(delivery, {title, description, actor='agent-local'}) {
  const now = new Date().toISOString();
  const data = {...delivery.route.output, description, visibility:'private', reflex:delivery.reflex};
  const values = {Identificador:delivery.reflex, 'Versió del document':'1.0.0', Entorn:'entorn-dev-local',
    'Creació':now, 'Modificació':now, Propietari:actor, 'Aprovació humana':'pendent', Plantilla:`${delivery.route.plantilla} (v${delivery.route.version})`, 'Model IA':'[pendent]', 'Tokens consumits':'[pendent]'};
  const body = delivery.route.seccions.map(section => {
    const content = delivery.route.fixedBlocks?.[section] ?? (section === 'Registre' ? '| Camp | Valor |\n| --- | --- |\n'+Object.entries(values).map(([k,v])=>`| ${k} | ${v} |`).join('\n')
      : section === 'Acte reflex' ? `Plantilla entregada: ${delivery.route.plantilla}; SHA-256 ${delivery.route.templateHash}. El rebut acredita entrega, no comprensió.`
      : section === 'Historial' ? `${now}: esborrany creat; contingut i verificació pendents.`
      : section === 'Vincles' ? '- [[00_index]]\n- [[00_index_escriptori]]' : '[pendent]');
    const sectionId=delivery.route.sectionIds?.[section];
    return `${sectionId ? `<!-- SDP:SECTION ${sectionId} -->\n` : ''}## ${section}\n\n${content}`;
  }).join('\n\n');
  const templateBody=parseDocument(delivery.template).body;
  const prelude=/^# [^\n]*\n([\s\S]*?)(?=^## )/m.exec(templateBody)?.[1]?.trim() || '';
  return `---\n${yaml.dump(data,{schema:yaml.JSON_SCHEMA,lineWidth:-1,noRefs:true})}---\n# ${title}\n\n${prelude ? prelude+'\n\n' : ''}${body}\n`;
}
export function createDraft(root, id, opts) {
  if (!opts.title || !opts.description) throw new Error('Cal --title i --description');
  root = fs.realpathSync(root);
  const file = path.resolve(root, opts.file);
  checkDraftDestinations(root, file);
  const delivery = deliverContext(root,id,opts);
  const raw = draft(delivery,opts);
  const contract = loadContract(root,{templates:false});
  const errors = validateSchema({...delivery.route.output,description:opts.description,visibility:'private',reflex:delivery.reflex},contract.schema);
  if (errors.length) throw new Error(errors.join('\n'));
  writeIndexedDraft(root, file, raw, { requireCleanTable: ['prompt.local', 'prompt.consell'].includes(delivery.route.id) });
  return {file:opts.file,reflex:delivery.reflex,state:'draft',note:'Completa les seccions [pendent] abans de validar.'};
}
async function main() {
  const o=options(), root=path.resolve(o.arrel || ROOT), command=o._[0];
  let result;
  if(o.help || !command) {
    console.log('Ús: document.mjs context|create|plan|check|own|handoff|import --turn-id ID --route ID --file CAMÍ\ncreate: --title TÍTOL --description DESCRIPCIÓ [--actor NOM]\nown: --file CAMÍ (repetix la comanda per cada fitxer)\nhandoff: --file ORIGEN --to DESTÍ (després del moviment explícit)\nRutes: '+loadContract(root,{templates:false}).router.rutes.map(r=>r.id).join(', '));
    return;
  }
  if(command==='import') {const {importDocument}=await import('../documental/import.mjs');result=importDocument(root,o['turn-id'],o);}
  else if(command==='own') result=ownPaths(root,o['turn-id'],[o.file]);
  else if(command==='handoff') result=handoffDocument(root,o['turn-id'],o.file,o.to);
  else if (command==='context') {
    const d=deliverContext(root,o['turn-id'],{route:o.route,file:o.file});
    result={reflex:d.reflex,route:d.route.id,template:d.template};
  } else if(command==='create') result=createDraft(root,o['turn-id'],{route:o.route,file:o.file,title:o.title,description:o.description,actor:o.actor});
  else if(command==='plan') {const t=bindPlan(root,o['turn-id'],o.file);result={turn_id:t.turn_id,state:t.state,plan:t.plan};}
  else if(command==='check') {const errors=validateDocument(root,fs.readFileSync(path.join(root,o.file),'utf8'),o.file,{closed:true});result={valid:!errors.length,errors};process.exitCode=errors.length?1:0;}
  else throw new Error('Ús: document.mjs context|create|plan|check --turn-id ID --route ID --file CAMÍ');
  console.log(JSON.stringify(result,null,2));
}
if (esMain(import.meta.url)) {
  main().catch(e=>{console.error(e.message);process.exitCode=1;});
}

